import random

movies = [
    "THE LION KING",
    "3 IDIOTS",
    "DANGAL",
    "LAGAAN",
    "INTERSTELLAR"
]

def create_question(movie):
    question = ""

    for ch in movie:
        if ch == " ":
            question += " "
        elif ch.isalpha():
            question += "*"
        else:
            question += ch

    return question

def is_present(letter, movie):
    return movie.count(letter) > 0

def unlock(question, movie, letter):
    result = ""

    for i in range(len(movie)):
        if movie[i] == letter:
            result += letter
        else:
            result += question[i]

    return result

movie = random.choice(movies)
question = create_question(movie)

print("Guess the movie:")
print(question)

while question != movie:
    letter = input("Enter a letter: ").upper()

    if is_present(letter, movie):
        question = unlock(question, movie, letter)
        print("Correct!")
    else:
        print("Letter not found.")

    print(question)

print("Congratulations! You guessed the movie.")

